package com.sunantongsan.xian2;
import org.junit.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import java.util.zip.*;import static org.junit.Assert.*;
public class SparseUpdaterTest {
 File root;Map<String,byte[]> assets,responses;JSONObject index;UpdateManifest release;List<String> requested;
 @Before public void setup()throws Exception{root=java.nio.file.Files.createTempDirectory("sparse-test").toFile();assets=new LinkedHashMap<>();responses=new HashMap<>();requested=new ArrayList<>();for(String name:new String[]{"index.html","game.js","core.js","style.css"})assets.put(name,("new "+name).getBytes(StandardCharsets.UTF_8));prepare();}
 @After public void cleanup(){GamePatch.remove(root);}
 String hash(byte[] data)throws Exception{return AutoUpdater.hex(MessageDigest.getInstance("SHA-256").digest(data));}
 byte[] zip(String name,byte[] data)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(b)){z.putNextEntry(new ZipEntry(name));z.write(data);z.closeEntry();}return b.toByteArray();}
 JSONObject payload(String name,byte[] data)throws Exception{byte[] bytes=zip(name,data);String sha=hash(bytes),path="patches/"+sha+".zip";responses.put("/"+path,bytes);return new JSONObject().put("path",path).put("sha256",sha).put("size",bytes.length);}
 void prepare()throws Exception{JSONObject files=new JSONObject();for(Map.Entry<String,byte[]> e:assets.entrySet())files.put(e.getKey(),payload(e.getKey(),e.getValue()).put("hash",hash(e.getValue())).put("bytes",e.getValue().length));index=new JSONObject().put("game","cockro").put("engine",88).put("version","4.42.0").put("files",files);setIndex();}
 void setIndex()throws Exception{JSONObject m=new JSONObject(AutoUpdaterTest.manifest(new byte[]{1}));m.put("version","4.42.0").put("sparse",payload("manifest.json",index.toString().getBytes(StandardCharsets.UTF_8)));release=new UpdateManifest(m.toString());}
 AutoUpdater updater(){return new AutoUpdater(url->{requested.add(url.getPath());byte[] data=responses.get(url.getPath());if(data==null)throw new IOException("unexpected download");return new AutoUpdaterTest.Response(url,data,200,data.length);});}
 SparseUpdater.Source existing(){return name->new ByteArrayInputStream(assets.get(name));}
 @Test public void unchangedAssetsNeedOnlySmallManifestAndReconstructedArchiveValidates()throws Exception{File zip=SparseUpdater.download(updater(),release,root,existing(),(d,t)->{});assertEquals(1,requested.size());File extracted=new File(root,"extract");extracted.mkdir();assertEquals("4.42.0",PatchArchive.extract(new FileInputStream(zip),extracted));for(String name:assets.keySet())assertArrayEquals(assets.get(name),java.nio.file.Files.readAllBytes(new File(extracted,name).toPath()));}
 @Test public void onlyChangedFileDownloadsAndProgressCountsTransferredBytes()throws Exception{long[] progress={0,0};SparseUpdater.download(updater(),release,root,name->new ByteArrayInputStream(name.equals("game.js")?new byte[]{0}:assets.get(name)),(d,t)->{progress[0]=d;progress[1]=t;});assertEquals(2,requested.size());assertEquals("/"+index.getJSONObject("files").getJSONObject("game.js").getString("path"),requested.get(1));assertEquals(progress[0],progress[1]);assertEquals(index.getJSONObject("files").getJSONObject("game.js").getLong("size"),progress[1]);}
 @Test public void missingOrCorruptLocalFilesDownloadAndObsoleteFilesAreOmitted()throws Exception{File zip=SparseUpdater.download(updater(),release,root,name->{throw new FileNotFoundException();},(d,t)->{});assertEquals(5,requested.size());File extracted=new File(root,"extract");extracted.mkdir();PatchArchive.extract(new FileInputStream(zip),extracted);assertEquals(5,extracted.list().length);requested.clear();SparseUpdater.download(updater(),release,root,name->{throw new FileNotFoundException();},(d,t)->{});assertEquals("completed content cache survives retry",1,requested.size());}
 @Test public void corruptRemoteFileCannotProduceInstallableArchive()throws Exception{String path="/"+index.getJSONObject("files").getJSONObject("game.js").getString("path");byte[] bytes=responses.get(path).clone();bytes[bytes.length/2]^=1;responses.put(path,bytes);try{SparseUpdater.download(updater(),release,root,name->new ByteArrayInputStream(name.equals("game.js")?new byte[]{0}:assets.get(name)),(d,t)->{});fail();}catch(IOException expected){}assertFalse(new File(root,"sparse-bundle.zip").exists());}
 @Test public void rejectsTraversalAndWrongReleaseBeforeReusingFiles()throws Exception{index.getJSONObject("files").put("../outside.js",index.getJSONObject("files").getJSONObject("game.js"));setIndex();try{SparseUpdater.download(updater(),release,root,existing(),(d,t)->{});fail();}catch(IOException expected){}assertFalse(new File(root.getParentFile(),"outside.js").exists());prepare();index.put("version","4.43.0");setIndex();try{SparseUpdater.download(updater(),release,root,existing(),(d,t)->{});fail();}catch(IOException expected){}}
 @Test public void cancelNeverProducesInstallableBundle()throws Exception{AutoUpdater u=updater();u.cancel();try{SparseUpdater.download(u,release,root,existing(),(d,t)->{});fail();}catch(IOException expected){}assertFalse(new File(root,"sparse-bundle.zip").exists());}
}
